const tideCrystalSheet=new Image();tideCrystalSheet.assetSrc='assets/tide-crystal-v2.png';
function beginTideCrystal(e){let angle=Math.atan2(p.y-e.y,p.x-e.x);e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'tideClosingWalls',bespoke:true,windup:1.1,origin:{x:e.x,y:e.y},center:{x:p.x,y:p.y},ux:Math.cos(angle),uy:Math.sin(angle),hits:[false,false],burst:false};}
function tideWallOffset(time){return 160-130*Math.max(0,Math.min(1,(time-1.1)/1.2));}
function tideWallContact(a,point,index,from,to){if(to<1.1||from>2.3)return null;let sign=index?1:-1,first=sign*tideWallOffset(Math.max(from,1.1)),last=sign*tideWallOffset(Math.min(to,2.3)),dx=point.x-a.center.x,dy=point.y-a.center.y,along=Math.max(-140,Math.min(140,dx*a.ux+dy*a.uy)),side=dx*(-a.uy)+dy*a.ux,clamped=Math.max(Math.min(first,last),Math.min(Math.max(first,last),side)),q={x:a.center.x+a.ux*along-a.uy*clamped,y:a.center.y+a.uy*along+a.ux*clamped};return dist(q,point)<=18+1e-8?q:null;}
const tideCrystalAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r8e1')return tideCrystalAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='tideClosingWalls'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=360&&clear){beginTideCrystal(e);return;}e.state='idle';if(d>800&&!e.aware||d<=240&&clear)return;if(e.nav<=0){e.nav=.7;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,68*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}let before=e.elapsed;e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 for(let i=0;i<2;i++){let contact=tideWallContact(a,p,i,before,e.elapsed);if(!dead&&!a.hits[i]&&!(p.inv>0)&&contact&&lineClear(a.origin,contact)&&lineClear(contact,p)){a.hits[i]=true;hurt(52);}}if(!a.burst&&e.elapsed>=2.9){a.burst=true;e.struck=true;if(!dead&&dist(p,a.center)<=90+1e-8&&lineClear(a.origin,a.center)&&lineClear(a.center,p))hurt(84);playSound('impact',a.center.x,a.center.y);}if(e.elapsed>=3.6){e.attack=null;e.state='idle';e.t=3;}
};
const tideCrystalDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r8e1'||!tideCrystalSheet.complete||!tideCrystalSheet.naturalWidth||!tideCrystalSheet.naturalHeight)return tideCrystalDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='tideClosingWalls')f={row:2,col:e.elapsed<1.1?0:e.elapsed<2.3?1:e.elapsed<3.1?2:3};let q=project(e.x,e.y),sw=tideCrystalSheet.naturalWidth/4,sh=tideCrystalSheet.naturalHeight/3,w=225,h=w*sh/sw,anchor=[.89,.88,.89][f.row];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,tideCrystalSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(tideCrystalSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const tideCrystalSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r8e1'?140:tideCrystalSizeBase(e);
function drawTideWall(a,side,active,spent){let points=[[-140,side-18],[140,side-18],[140,side+18],[-140,side+18]].map(([along,across])=>({x:a.center.x+a.ux*along-a.uy*across,y:a.center.y+a.uy*along+a.ux*across}));ctx.save();ctx.fillStyle=active&&!spent?'#70d9ee66':'#70b0c222';ctx.strokeStyle=spent?'#6b9aa8':'#b2edf2';ctx.lineWidth=active?2:1;ctx.beginPath();points.forEach((point,i)=>{let q=project(point.x,point.y);if(i)ctx.lineTo(q.x,q.y);else ctx.moveTo(q.x,q.y);});ctx.closePath();ctx.fill();ctx.stroke();ctx.restore();for(let along of [-140,140])groundRing(a.center.x+a.ux*along-a.uy*side,a.center.y+a.uy*along+a.ux*side,18,spent?'#6b9aa8':'#b2edf2',1);}
const tideCrystalGroundBase=drawGroundEffects;drawGroundEffects=()=>{tideCrystalGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r8e1'):enemies)){let a=e.attack;if(e.species!=='r8e1'||e.hp<=0||a?.pattern!=='tideClosingWalls'||!visibleAt(a.center.x,a.center.y))continue;if(e.elapsed<=2.3)for(let i=0;i<2;i++)drawTideWall(a,(i?1:-1)*tideWallOffset(e.elapsed),e.elapsed>=1.1,a.hits[i]);if(e.elapsed>=2.3&&e.elapsed<3.1)groundRing(a.center.x,a.center.y,90,a.burst?'#e0ffff':'#8edce7',a.burst?3:2);}};
